SELECT
 s.serial_number AS numero_kit,
 s.product_reference AS reference_produit,
 s.product_name AS produit,
 s.status AS crm_status,
 s.holder_id AS identifiant_agent,
 coalesce(s.holder_name,ag.agent_name) AS vendeur_ou_detenteur,
 ag.role AS role_agent,
 CASE WHEN s.status='DEPLOYED' THEN 'Vendeur' ELSE 'Detenteur' END AS rattachement_recherche,
 count(*) OVER() AS total_sans_zone
FROM selected s
LEFT JOIN bi_schema.dim_agents ag ON ag.agent_number=s.holder_id
WHERE EXISTS (SELECT 1 FROM non_rattaches n
 WHERE s.holder_id IS NOT DISTINCT FROM n.holder_id
 AND s.routing_shop_id IS NOT DISTINCT FROM n.routing_shop_id)
ORDER BY vendeur_ou_detenteur NULLS FIRST,numero_kit;
